//! Exercises items generated by a macro from another crate.
//!
//! `Counter` and `Counter::incr` are defined in `macrolib/src/lib.rs`, but
//! charon reports the macro invocation as their span, so they go into the
//! `Viamacro` module.

macrolib::define_counter!(Counter);

pub fn make() -> Counter {
    Counter { value: 0 }
}
